package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.index.CompoundIndex; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; import java.util.List;
@Document("reviews") @CompoundIndex(name="review_user_booking_unique",def="{'userId':1,'bookingId':1}",unique=true) public class Review {
 public enum TargetType { HOTEL, FLIGHT } public enum Status { PENDING, APPROVED, HIDDEN, REMOVED }
 @Id private String id; @Indexed private String userId; private String bookingId; private TargetType targetType; @Indexed private String targetId; private int rating; private String text; private List<String> photos; private int helpfulCount; private Status status=Status.PENDING; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now();
 public String getId(){return id;} public String getUserId(){return userId;} public void setUserId(String x){userId=x;} public String getBookingId(){return bookingId;} public void setBookingId(String x){bookingId=x;} public TargetType getTargetType(){return targetType;} public void setTargetType(TargetType x){targetType=x;} public String getTargetId(){return targetId;} public void setTargetId(String x){targetId=x;} public int getRating(){return rating;} public void setRating(int x){rating=x;} public String getText(){return text;} public void setText(String x){text=x;} public List<String> getPhotos(){return photos;} public void setPhotos(List<String> x){photos=x;} public int getHelpfulCount(){return helpfulCount;} public void setHelpfulCount(int x){helpfulCount=x;} public Status getStatus(){return status;} public void setStatus(Status x){status=x;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void touch(){updatedAt=Instant.now();}
}
